        flags |= negative;
        current = static_cast<std::uint8_t>(*cursor++);
    } else if (current == '+') {
        current = static_cast<std::uint8_t>(*cursor++);
    }
    if (radix < 0 || radix == 1 || radix > 36) {
        if (endPointer != nullptr) {
            *endPointer = const_cast<char*>(text);
        }
        return 0;
    }
    if (radix == 0) {
        if (current != '0') {
            radix = 10;
        } else {
