    } else if ((flags & overflow) != 0
        || ((flags & unsignedResult) == 0
            && value > ((flags & negative) != 0 ? 0x80000000u : 0x7FFFFFFFu))) {
        gLegacyErrno_1085FE0 = 34;
        value = (flags & unsignedResult) != 0 ? 0xFFFFFFFFu
            : ((flags & negative) != 0 ? 0x80000000u : 0x7FFFFFFFu);
